INSERT INTO questions_entretien (id,candidat_id,questions_json,posees_json,coche_par_json,updated_at) VALUES (6,6,'["Comment construisez-vous un tableau de bord de gestion permettant de piloter efficacement les indicateurs financiers et opérationnels d''une structure publique ?", "Quelles méthodes utilisez-vous pour analyser les écarts entre le budget prévisionnel et l''exécution budgétaire, et quelles actions correctives proposez-vous généralement ?", "Comment abordez-vous la mise en place d''un contrôle interne dans un environnement où les procédures sont encore peu formalisées ?", "Pouvez-vous décrire une mission concrète de contrôle de gestion que vous avez menée durant vos 6 années d''expérience, en précisant votre méthodologie et les résultats obtenus ?", "Avez-vous déjà travaillé sur des projets impliquant plusieurs directions ou parties prenantes ? Comment avez-vous géré les tensions éventuelles autour des données chiffrées ?", "En quoi votre formation à l''ENCG vous a-t-elle préparé aux spécificités du contrôle de gestion dans le secteur public ou para-public ?", "Qu''est-ce qui vous motive à rejoindre l''ADER plutôt qu''une structure privée, alors que votre profil aurait clairement de la valeur dans les deux univers ?", "Où vous voyez-vous dans 5 ans au sein d''une agence de développement régional, et quel rôle souhaitez-vous jouer dans l''évolution de la structure ?", "Que savez-vous des missions de l''ADER Fès-Meknès et de son rôle dans le cadre de la régionalisation avancée au Maroc ?", "Quelles sont, selon vous, les principales contraintes budgétaires et réglementaires auxquelles font face les établissements publics marocains, et comment le contrôle de gestion peut-il y apporter une réponse ?"]','[]','{}','2026-08-27 13:26:33.183410') ON CONFLICT (id) DO NOTHING;